    pm.expect(location).to.have.property('lat');
    pm.expect(location.lat).to.be.a('number');
    pm.expect(location).to.have.property('lon');
    pm.expect(location.lon).to.be.a('number');
    let user = responseBody.initiator; // получаем значение поля user
    pm.expect(user).to.have.property('id');
    pm.expect(user.id).to.be.a('number');

